{
  "name": "build_chaingraph",
  "description": "Hash-aware sibling of build_workflow_links (ChainGraph Standard v0.1 §8.1). Returns an ordered, executable DAG over the ChainGraph suite's verifiable tools, with explicit parent_hash wiring: which upstream execution_hash each step must cite in its chain block. Pass target_tool_id to build the chain that produces that node (walks consumes-edges back to roots), or tool_ids for an explicit ordered list, or neither to list available ChainGraph nodes. Agent loop: run a node, capture its execution_hash, pass it as the parent_hash for each downstream node, then verify with verify_execution_hash.",
  "inputSchema": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "type": "object",
    "properties": {
      "target_tool_id": {
        "description": "A ChainGraph node tool_id (e.g. \"art-15-agent-commerce-conformance\"). Builds the chain that produces it.",
        "type": "string"
      },
      "tool_ids": {
        "description": "Explicit ordered list of ChainGraph node tool_ids to wire.",
        "type": "array",
        "items": {
          "type": "string"
        }
      }
    }
  }
}

{
  "name": "build_session_receipt",
  "description": "Aggregates execution_hashes from N ChainGraph tool calls in one agent session into a single SHA-256 Merkle root (session_receipt_root). Returns a tamper-evident session receipt and a regulator-framed PTG-01 audit prompt. One receipt covers an entire agent session: supply all execution_hashes in call order. The Merkle root is deterministic — the same hashes in the same order always produce the same root. Compliant with EU AI Act Art. 12 (transparency) and DORA ICT audit-trail requirements.",
  "inputSchema": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "type": "object",
    "properties": {
      "execution_hashes": {
        "type": "array",
        "items": {
          "type": "string"
        },
        "description": "Ordered list of execution_hash values from ChainGraph tool calls in this session (each produced by emit_chaingraph_artifact or a kernel tool). Minimum 1."
      },
      "tool_ids": {
        "description": "tool_id values corresponding to execution_hashes, in the same order. Used for the audit narrative.",
