{
  "name": "emit_chaingraph_artifact",
  "description": "Makes ChainGraph tools agent-callable (ChainGraph Standard v0.1 §3.1). Mode 1 — supply pre_computed_artifact (exported from the browser tool): validates §4 schema fields, recomputes execution_hash via SHA-256 over canonical {policy_parameters, output_payload}, returns verified structuredContent. Mode 2 — supply tool_id + policy_parameters: returns an artifact template envelope and browser prefill URL so an agent can hand the user a pre-filled link; GPU sims always delegate to the browser per §9.2. Mode 3 — supply tool_id only: returns node metadata and artifact schema scaffold. Mode 4 (Compute Binding, v0.4) — supply tool_id + policy_parameters + compute:\"server\" (or compute:\"auto\" for gpu:false nodes): runs the registered kernel server-side and returns a verified v0.4 artifact with execution_hash + output_payload in one round-trip. No browser required. gpu:true nodes always delegate to browser. Hashed input must be I-JSON (RFC 7493): integers beyond 2^53 must be passed as JSON strings, and NaN/Infinity are rejected — values outside I-JSON have no stable canonical form, so a structured -32602 error (error.data.reason \"ijson_violation\") is returned instead of an execution_hash. readOnlyHint: true. Zero PII, zero payload logging. Pair with verify_execution_hash (independent hash verification) and build_chaingraph (DAG wiring).",
  "inputSchema": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "type": "object",
    "properties": {
      "tool_id": {
        "description": "ChainGraph node tool_id (e.g. \"art-01-ap2-mandate-chain-validator\"). Looked up in chaingraph.json nodes. Required unless pre_computed_artifact is supplied.",
        "type": "string"
      },
      "policy_parameters": {
        "description": "Input parameters for the tool (mirrors the tool's Policy Mandate input fields). Used for Mode 2 browser prefill and Mode 4 server-side compute.",
        "type": "object",
        "propertyNames": {
          "type": "string"
        },
        "additionalProperties": {}
      },
      "compute": {
        "description": "Compute mode (v0.4 Compute Binding). \"auto\" = server for gpu:false nodes (default); \"server\" = force server-side; \"browser\" = always return browser delegation URL. gpu:true nodes always use browser regardless of this flag.",
        "type": "string",
        "enum": [
          "auto",
          "server",
          "browser"
        ]
      },
      "parent_hashes": {
        "description": "execution_hash values from upstream ChainGraph artifacts this call chains from. Placed into artifact.chain.parent_hashes (ChainGraph Standard v0.1 §5 chain block).",
        "type": "array",
        "items": {
          "type": "string"
        }
      },
      "parent_tool_ids": {
        "description": "tool_ids corresponding to parent_hashes, in the same order.",
        "type": "array",
        "items": {
          "type": "string"
        }
      },
      "pre_computed_artifact": {
        "description": "A full ChainGraph artifact envelope previously exported from the browser tool via \"Export Policy Mandate\". When supplied, the worker validates §4 required fields, recomputes execution_hash, and returns a verified structuredContent. This is the recommended path: run the tool in-browser, export JSON, call emit_chaingraph_artifact to verify and receive a structured receipt.",
        "type": "object",
        "propertyNames": {
          "type": "string"
        },
        "additionalProperties": {}
      }
    }
  }
}

{
  "name": "find_chain",
  "description": "BM25 search over all 415 AINumbers ChainGraph chains. Returns ranked chains with their full recipe: ordered node sequence, deep-links, composer URL, and entry tool mcp_name. Agent flow: find_chain(query) → read recipe → call the listed node MCP tools in order, passing parent_hashes between steps. Task-shaped queries work well: \"reserve composition recompute\", \"FR 2052a classification\", \"CCP margin replication\", \"SR 26-2 model validation benchmark\", \"litigation damages recompute\", \"evidence pack assembly\".",
  "inputSchema": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "type": "object",
    "properties": {
      "query": {
        "type": "string",
        "description": "Natural-language or keyword search (e.g. \"AML programme\", \"DORA ICT readiness\", \"MiCA CASP\", \"PQC migration\", \"Basel capital\", \"reserve composition\", \"2052a classification\", \"CCP margin\", \"model validation benchmark\", \"damages recompute\", \"evidence pack\")."
      },
      "top_n": {
        "description": "Max results to return (default 5).",
        "type": "number",
        "minimum": 1,
        "maximum": 20
      }
    },
    "required": [
      "query"
    ]
  }
}

{
  "name": "run_chain",
  "description": "Executes every step of a named chain (list names with find_chain / build_workflow_links) and returns ONE composite artifact whose execution_hash anchors all step outputs. compute:\"server\"/\"auto\" (default) runs each kernel-backed step server-side, threading step N's execution_hash into step N+1's parent_hashes; compute:\"browser\" returns a zero-egress delegation bundle (composer URL + ordered deep-links) to run client-side instead — no data leaves the agent. Supply inputs as a map of step tool_id -> policy_parameters (field names per node manifest / build_chaingraph); a step whose kernel needs inputs you omit is reported per-step (status \"input_required\"), never failed silently. Steps that are browser-only (gpu:true or no registered kernel) are listed for browser delegation. Deterministic, zero PII, zero payload logging. Verify the result with verify_execution_hash. Runs with anything to explain carry decision_trail: per-step reason codes (gate rule id, escalation rule id, input_required cause), hash-excluded adjacent metadata recomputable from the hash-bound decisions[]. Each server-mode run also returns an OpenTelemetry GenAI span document as a resource link (one execute_tool span per executed step under an invoke_agent parent). Response includes a ledger_url fragment link for human verification at ledger.ainumbers.co. Server-mode responses also echo a stable `dedupe` object — `dedupe.input_hash` (JCS-SHA-256 over the effective run inputs: chain, per-step inputs after the caller/fixture fallback, and mandate_hash when a mandate governs) beside `dedupe.composite_execution_hash` — so a client can recognize and skip an exact re-run (idempotentHint) without recomputing anything. See docs/IDEMPOTENCY.md.",
  "inputSchema": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "type": "object",
    "properties": {
      "chain": {
        "type": "string",
        "description": "Chain name, e.g. \"agent-commerce-conformance\". List names with find_chain or build_workflow_links."
      },
      "inputs": {
        "description": "Map of step tool_id -> policy_parameters overrides. Omitted steps run with {} (kernels needing required fields are reported, not failed silently).",
        "type": "object",
        "propertyNames": {
          "type": "string"
        },
        "additionalProperties": {
          "type": "object",
          "propertyNames": {
            "type": "string"
          },
          "additionalProperties": {}
        }
      },
      "compute": {
        "description": "\"auto\"/\"server\" (default) runs kernel-backed steps server-side; \"browser\" returns a zero-egress delegation bundle to run client-side.",
        "type": "string",
        "enum": [
          "auto",
          "server",
          "browser"
        ]
      },
      "escalation_transport": {
        "description": "How an OCG §22.8 escalation is delivered. \"resolve_handle\" (DEFAULT) never blocks: the run COMPLETES with status \"escalated\" plus the open record, its record_hash and a resolve handle, and a human closes it out of band. \"input_required\" opts into the SEP-2322 multi-round-trip: the call answers with an InputRequiredResult asking for the §22.8.4 closure, and the retry (echoing requestState) resolves the record inline.",
        "type": "string",
        "enum": [
          "resolve_handle",
          "input_required"
        ]
      },
      "mandate": {
        "description": "Optional §22 Work Mandate artifact. When supplied: §16 signature is verified and validity window is checked (unsigned/bad-sig/expired returns a structured error); mandate_hash is folded into every step and the composite receipt as a conditional-presence key, proving which policy governed this run. A no-mandate run is byte-identical to the pre-binding baseline (linear-hash-freeze invariant).",
        "type": "object",
        "properties": {},
        "additionalProperties": {}
      }
    },
    "required": [
      "chain"
    ]
  }
}

{
  "name": "vc_issue",
  "description": "Composes and signs a W3C Verifiable Credential 2.0 with an eddsa-jcs-2022 Data Integrity proof over a fresh ephemeral did:key (generated per call, not reused). Returns the signed credential, an OCG Standard §23 vc-2.0 input-attestation block ready to embed in a ChainGraph chain's policy_parameters at the given pointer, and an OCG receipt of the issuance activity. The signature proves the claims were not altered after signing and that the did:key holder produced it -- it is not, by itself, identity assurance.",
  "inputSchema": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "type": "object",
    "properties": {
      "claims": {
        "type": "object",
        "propertyNames": {
          "type": "string"
        },
        "additionalProperties": {},
        "description": "Claim key-value pairs for credentialSubject (required, at least one entry)."
      },
      "subject_id": {
        "description": "Credential subject id (DID or any identifier string). Default: \"did:example:subject\".",
        "type": "string"
      },
      "credential_type": {
        "description": "Type appended to VerifiableCredential (e.g. \"MembershipCredential\").",
        "type": "string"
      },
      "valid_from": {
        "description": "ISO 8601 validFrom. Default: now.",
        "type": "string"
      },
      "valid_until": {
        "description": "ISO 8601 validUntil.",
        "type": "string"
      },
      "pointer": {
        "description": "RFC 6901 JSON pointer where the attestation's claims sit in a consuming chain's policy_parameters. Default: \"/subject_claims\".",
        "type": "string"
      }
    },
    "required": [
      "claims"
    ]
  }
}

