{
  "name": "anchor_stamp",
  "description": "Calls the anchor-suite MCP server (server-to-server, not the browser CORS-gated relay) to timestamp one execution_hash, or batch-anchor an array via anchor-suite's own anchor_batch (one upstream call per batch, RFC 6962 Merkle root anchored, per-hash merkle_inclusion returned), and shapes the result as literal OCG v0.7 section 20 anchor_bindings entries ready to append to an artifact. Success is only reported after this tool independently confirms anchored_hash (or, for a batch entry, merkle_inclusion.leaf) equals the caller-supplied hash -- it does not merely trust anchor-suite's response. On ANY failure -- anchor-suite unreachable, erroring, timing out, or an equality mismatch -- returns {ok:false, unanchored:true, reason} verbatim, never a fabricated binding. Caller-invoked only; not wired into any automatic per-artifact-emission path.",
  "inputSchema": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "type": "object",
    "properties": {
      "execution_hash": {
        "anyOf": [
          {
            "type": "string",
            "description": "A single sha256:... execution_hash to anchor."
          },
          {
            "minItems": 2,
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "2+ execution_hash values to batch-anchor in one upstream call (anchor_batch)."
          }
        ],
        "description": "The execution_hash(es) to anchor."
      },
      "authority": {
        "description": "Defaults to whatever anchor-suite's own anchor_hash/anchor_batch default to today (currently sigstore for rfc3161-tst) -- this tool does not own or hardcode a preference beyond that mirror.",
        "type": "string",
        "enum": [
          "rfc3161-tst",
          "opentimestamps"
        ]
      }
    },
    "required": [
      "execution_hash"
    ]
  }
}

{
  "name": "build_evidence_pack",
  "description": "Composes a session receipt (build_session_receipt logic), an optional §27.6 HA evidence bundle (ha_bundle_export logic, included only when ha_records is supplied and non-empty), and a disclosure manifest (build_disclosure_manifest logic) from one array of already-produced artifacts, all keyed to the same input hashes -- replacing what today takes 4-6 separate tool calls with hand-carried hashes. Calls the same in-process functions those standalone tools use; if any one section fails to build, the whole call fails isError:true with that section's own message -- no partial pack. Optionally carries a run_chain decision_trail (per-step reason codes: gate rule id, escalation rule id, input_required cause) as pack-level metadata so an auditor-facing pack answers \"why did each step happen\" without a second round-trip.",
  "inputSchema": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "type": "object",
    "properties": {
      "artifacts": {
        "minItems": 1,
        "type": "array",
        "items": {
          "type": "object",
          "properties": {
            "execution_hash": {
              "type": "string",
              "description": "sha256:... -- the OCG artifact hash this entry documents."
            },
            "tool_id": {
              "description": "The tool_id that produced this artifact, if known.",
              "type": "string"
            },
            "output_payload": {
              "description": "Present when caller has the full artifact, not just its hash.",
              "type": "object",
              "propertyNames": {
                "type": "string"
              },
              "additionalProperties": {}
            }
          },
          "required": [
            "execution_hash"
          ]
        },
        "description": "Already-produced artifacts this pack documents, in call order."
      },
      "subject_hash": {
        "description": "The sha256: subject hash the pack documents (defaults to artifacts[0].execution_hash if omitted).",
        "type": "string"
      },
      "ha_records": {
        "description": "§27 human_accountability_records -- omit entirely for no HA section.",
        "type": "array",
        "items": {
          "type": "object",
          "propertyNames": {
            "type": "string"
          },
          "additionalProperties": {}
        }
      },
      "kernel_version": {
        "description": "Version tag of the kernel that produced verification_result.",
        "type": "string"
      },
      "policy_version": {
        "description": "Version tag of the policy the kernel was evaluated against.",
        "type": "string"
      },
      "verification_result": {
        "description": "The §16/§18/§20 verdict.",
        "type": "string"
      },
      "submission_receipt": {
        "description": "Populate ONLY after a real transmission -- never fabricate (same rule as ha_bundle_export).",
        "type": "string"
      },
      "session_id": {
        "description": "Session identifier to embed in the receipt, if the caller tracks one.",
        "type": "string"
      },
      "framing": {
        "description": "Optional framing context for the session receipt's PTG-01 regulator prompt.",
        "type": "string"
      },
      "room_label": {
        "description": "Label for the disclosure-manifest room.",
        "type": "string"
      },
      "decision_trail": {
        "description": "Per-step decision reason trail from the run_chain result (pass its decision_trail — response field or composite_output.decision_trail). Carried verbatim into the pack as pack-level metadata, outside every section hash; omitted entirely when not supplied. See DECISIONTRAIL-1.",
        "type": "array",
        "items": {
          "type": "object",
          "properties": {
            "order": {
              "type": "integer",
              "minimum": -9007199254740991,
              "maximum": 9007199254740991,
              "description": "1-based step order, mirroring the producing run_chain result."
            },
            "tool_id": {
              "type": "string",
              "description": "The step's tool_id."
            },
            "status": {
              "type": "string",
              "description": "Per-step status from the run_chain result."
            },
            "reason_code": {
              "type": "string",
              "description": "Closed enum: ran | gate_routed | skipped_by_gate | skipped_by_escalation | input_required | unknown_node | gpu_browser_only | no_kernel_browser_only."
            },
            "gate_rule_id": {
              "description": "<step_id>#r<index> or <step_id>#default — the gate rule that fired or bypassed this step. Recomputable from the hash-bound decisions[].",
              "type": "string"
            },
            "decided_by": {
              "description": "step_id of the decision that routed control past this step.",
              "type": "string"
            },
            "next": {
              "description": "Routing target of the gate decision (a step id, or the terminal \"end\"/\"escalate\").",
              "type": "string"
            },
            "input_required_cause": {
              "description": "The kernel error that made this step input_required.",
              "type": "string"
            }
          },
          "required": [
            "order",
            "tool_id",
            "status",
            "reason_code"
          ]
        }
      },
      "sd_jwt": {
        "description": "When true, also return an SD-JWT export of the HA bundle (mirrors ha_bundle_export, default false; no-op when ha_records is absent).",
        "type": "boolean"
      }
    },
    "required": [
      "artifacts"
    ]
  }
}

