{
  "name": "anchor_stamp",
  "description": "Calls the anchor-suite MCP server (server-to-server, not the browser CORS-gated relay) to timestamp one execution_hash, or batch-anchor an array via anchor-suite's own anchor_batch (one upstream call per batch, RFC 6962 Merkle root anchored, per-hash merkle_inclusion returned), and shapes the result as literal OCG v0.7 section 20 anchor_bindings entries ready to append to an artifact. Success is only reported after this tool independently confirms anchored_hash (or, for a batch entry, merkle_inclusion.leaf) equals the caller-supplied hash -- it does not merely trust anchor-suite's response. On ANY failure -- anchor-suite unreachable, erroring, timing out, or an equality mismatch -- returns {ok:false, unanchored:true, reason} verbatim, never a fabricated binding. Caller-invoked only; not wired into any automatic per-artifact-emission path.",
  "inputSchema": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "type": "object",
    "properties": {
      "execution_hash": {
        "anyOf": [
          {
            "type": "string",
            "description": "A single sha256:... execution_hash to anchor."
          },
          {
            "minItems": 2,
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "2+ execution_hash values to batch-anchor in one upstream call (anchor_batch)."
          }
        ],
        "description": "The execution_hash(es) to anchor."
      },
      "authority": {
        "description": "Defaults to whatever anchor-suite's own anchor_hash/anchor_batch default to today (currently sigstore for rfc3161-tst) -- this tool does not own or hardcode a preference beyond that mirror.",
        "type": "string",
        "enum": [
          "rfc3161-tst",
          "opentimestamps"
        ]
      }
    },
    "required": [
      "execution_hash"
    ]
  }
}

{
  "name": "build_session_receipt",
  "description": "Aggregates execution_hashes from N ChainGraph tool calls in one agent session into a single SHA-256 Merkle root (session_receipt_root). Returns a tamper-evident session receipt and a regulator-framed PTG-01 audit prompt. One receipt covers an entire agent session: supply all execution_hashes in call order. The Merkle root is deterministic — the same hashes in the same order always produce the same root. Compliant with EU AI Act Art. 12 (transparency) and DORA ICT audit-trail requirements.",
  "inputSchema": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "type": "object",
    "properties": {
      "execution_hashes": {
        "type": "array",
        "items": {
          "type": "string"
        },
        "description": "Ordered list of execution_hash values from ChainGraph tool calls in this session (each produced by emit_chaingraph_artifact or a kernel tool). Minimum 1."
      },
      "tool_ids": {
        "description": "tool_id values corresponding to execution_hashes, in the same order. Used for the audit narrative.",
        "type": "array",
        "items": {
          "type": "string"
        }
      },
      "session_id": {
        "description": "Optional agent session identifier for the audit narrative (e.g. a UUID or timestamp).",
        "type": "string"
      },
      "framing": {
        "description": "Optional framing context for the PTG-01 regulator prompt (e.g. \"DORA incident review\" or \"EU AI Act Art.12 transparency log\").",
        "type": "string"
      },
      "prior_receipt": {
        "description": "An earlier receipt from this SAME session (its mmr_peaks/mmr_size/mmr_bagged_root). When supplied, execution_hashes MUST start with that earlier receipt's full leaf set — the response's consistency_proof then proves this receipt provably APPENDS to the prior one (CT-style append-only guarantee) without operating a log.",
        "type": "object",
        "properties": {
          "mmr_peaks": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "mmr_size": {
            "type": "number"
          },
          "mmr_bagged_root": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ]
          }
        },
        "required": [
          "mmr_peaks",
          "mmr_size"
        ]
      }
    },
    "required": [
      "execution_hashes"
    ]
  }
}

{
  "name": "redline_diff",
  "description": "An agent proposes an edit: diffs original text/markdown against its own revised version and returns the line-level hunks plus a diff receipt (original/revised digests, diff-algorithm declaration, per-hunk digests). Byte-identical to what the tools/552 browser workbench computes for the same inputs -- a human can paste the SAME original/revised text into that workbench, disposition each hunk (accept/reject/comment), and their resulting hunk/disposition receipts will reference this diff_receipt's execution_hash. Pass the whole bundle (this diff_receipt + the human's hunk_receipts + disposition_receipt) to redline_verify to check the interleaved chain end-to-end.",
  "inputSchema": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "type": "object",
    "properties": {
      "original": {
        "type": "string",
        "description": "Original text or markdown document."
      },
      "revised": {
        "type": "string",
        "description": "Proposed revised text or markdown document."
      },
      "generated_at": {
        "description": "ISO 8601 timestamp (caller-supplied for determinism). Defaults to the call time.",
        "type": "string"
      }
    },
    "required": [
      "original",
      "revised"
    ]
  }
}

{
  "name": "redline_verify",
  "description": "Recomputes a redline review from scratch: the diff (from the pasted original+revised text), the diff_receipt's execution_hash, every hunk_receipt's digest/execution_hash/chain-link (in the order supplied -- entries may be minted by an agent, a human, or both interleaved), the disposition_receipt's execution_hash, and the accepted-text digest. Returns valid:true/false, a per-check breakdown, and broken_hunk (the zero-based index of the first divergence, or null) -- never trusts a bundle claim without checking it against a fresh recomputation.",
  "inputSchema": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "type": "object",
    "properties": {
      "original": {
        "type": "string",
        "description": "Original text or markdown document."
      },
      "revised": {
        "type": "string",
        "description": "Revised text or markdown document."
      },
      "bundle": {
        "type": "object",
        "properties": {
          "diff_receipt": {
            "type": "object",
            "propertyNames": {
              "type": "string"
            },
            "additionalProperties": {},
            "description": "The diff receipt (from redline_diff or the browser workbench)."
          },
          "hunk_receipts": {
            "type": "array",
            "items": {
              "type": "object",
              "propertyNames": {
                "type": "string"
              },
              "additionalProperties": {}
            },
            "description": "Ordered hunk disposition receipts, one per hunk index."
          },
          "disposition_receipt": {
            "type": "object",
            "propertyNames": {
              "type": "string"
            },
            "additionalProperties": {},
            "description": "The closing disposition receipt binding the accepted-text digest."
          }
        },
        "required": [
          "diff_receipt",
          "hunk_receipts",
          "disposition_receipt"
        ],
        "description": "The redline receipt bundle to verify."
      }
    },
    "required": [
      "original",
      "revised",
      "bundle"
    ]
  }
}

