{
  "name": "build_session_receipt",
  "description": "Aggregates execution_hashes from N ChainGraph tool calls in one agent session into a single SHA-256 Merkle root (session_receipt_root). Returns a tamper-evident session receipt and a regulator-framed PTG-01 audit prompt. One receipt covers an entire agent session: supply all execution_hashes in call order. The Merkle root is deterministic — the same hashes in the same order always produce the same root. Compliant with EU AI Act Art. 12 (transparency) and DORA ICT audit-trail requirements.",
  "inputSchema": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "type": "object",
    "properties": {
      "execution_hashes": {
        "type": "array",
        "items": {
          "type": "string"
        },
        "description": "Ordered list of execution_hash values from ChainGraph tool calls in this session (each produced by emit_chaingraph_artifact or a kernel tool). Minimum 1."
      },
      "tool_ids": {
        "description": "tool_id values corresponding to execution_hashes, in the same order. Used for the audit narrative.",
        "type": "array",
        "items": {
          "type": "string"
        }
      },
      "session_id": {
        "description": "Optional agent session identifier for the audit narrative (e.g. a UUID or timestamp).",
        "type": "string"
      },
      "framing": {
        "description": "Optional framing context for the PTG-01 regulator prompt (e.g. \"DORA incident review\" or \"EU AI Act Art.12 transparency log\").",
        "type": "string"
      },
      "prior_receipt": {
        "description": "An earlier receipt from this SAME session (its mmr_peaks/mmr_size/mmr_bagged_root). When supplied, execution_hashes MUST start with that earlier receipt's full leaf set — the response's consistency_proof then proves this receipt provably APPENDS to the prior one (CT-style append-only guarantee) without operating a log.",
        "type": "object",
        "properties": {
          "mmr_peaks": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "mmr_size": {
            "type": "number"
          },
          "mmr_bagged_root": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ]
          }
        },
        "required": [
          "mmr_peaks",
          "mmr_size"
        ]
      }
    },
    "required": [
      "execution_hashes"
    ]
  }
}

{
  "name": "checklist_step_receipt",
  "description": "Completes ONE step of a checklist/SOP run and returns its OCG v0.4 step receipt: execution_hash chains to prev_step_receipt_digest (pass the previous step's execution_hash, or omit for step 0). A blocking-gate step with evidence_requirement != \"none\" and no evidence supplied is refused (the caller enforces step order; this tool enforces the evidence requirement per step). Call once per step in order, then pass the full ordered list of returned receipts to checklist_verify_run to check the chain and mint the run receipt.",
  "inputSchema": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "type": "object",
    "properties": {
      "definition_digest": {
        "type": "string",
        "description": "The definition_digest from checklist_validate_definition."
      },
      "step": {
        "type": "object",
        "properties": {
          "step_id": {
            "type": "string",
            "description": "The step's unique id within the definition, e.g. \"s1\"."
          },
          "title": {
            "type": "string",
            "description": "Human-readable step title."
          },
          "instruction": {
            "description": "The step's instruction text (for the receipt narrative; not hashed separately from the step object).",
            "type": "string"
          },
          "evidence_requirement": {
            "type": "string",
            "enum": [
              "none",
              "text",
              "file-digest",
              "attestation"
            ],
            "description": "What evidence this step requires before it can be completed."
          },
          "approver_role": {
            "description": "Role required to approve this step, if any.",
            "type": "string"
          },
          "gate": {
            "type": "string",
            "enum": [
              "blocking",
              "advisory"
            ],
            "description": "Whether this step blocks the next step until completed (blocking) or can be skipped (advisory)."
          }
        },
        "required": [
          "step_id",
          "title",
          "evidence_requirement",
          "gate"
        ],
        "description": "The step object from the definition's steps[] array being completed."
      },
      "step_index": {
        "type": "integer",
        "minimum": 0,
        "maximum": 9007199254740991,
        "description": "Zero-based index of this step in the definition."
      },
      "timestamp": {
        "type": "string",
        "description": "ISO 8601 completion timestamp (caller-supplied for determinism)."
      },
      "completer_key": {
        "description": "Identifier of who/what completed the step (e.g. an agent id). Never real PII.",
        "type": "string"
      },
      "evidence": {
        "description": "Evidence payload, e.g. { text_digest }, { file_sha256 }, or { attestation_digest }. Required unless evidence_requirement is \"none\".",
        "type": "object",
        "propertyNames": {
          "type": "string"
        },
        "additionalProperties": {}
      },
      "prev_step_receipt_digest": {
        "description": "execution_hash of the previous step's receipt. Omit for the first step in the run.",
        "type": "string"
      }
    },
    "required": [
      "definition_digest",
      "step",
      "step_index",
      "timestamp"
    ]
  }
}

