{
  "name": "verify_execution_hash",
  "description": "Independently verify a ChainGraph artifact (ChainGraph Standard v0.1 §6). Recomputes SHA-256 over the canonical (sorted-key, whitespace-stripped) JSON of policy_parameters + output_payload and compares it to the claimed execution_hash. A match proves integrity: policy_parameters and output_payload are byte-for-byte what was hashed. It does not by itself show the outputs were computed from the inputs; for that, re-run the stage and compare (SPEC §4), or check the artifact's compute_proof where one is present (SPEC §18). Pass either a full artifact object, or policy_parameters + output_payload + claimed_hash. Inputs must be I-JSON (RFC 7493): integers beyond 2^53 must be passed as JSON strings, and NaN/Infinity are rejected. Values outside I-JSON have no stable canonical form, so this tool returns a structured -32602 error (error.data.reason \"ijson_violation\") instead of a hash. Pure client-safe compute -- no data is stored. Use this to verify artifacts from any vendor that conforms to the ChainGraph Standard. Also verifies composite chain artifacts from run_chain (composite_artifact, ChainGraph SPEC §21.2/§21.4): hash-excluded adjacent metadata such as decision_trail, step_compliance_flags, non_live_steps and escalation_record is dropped before recompute, and the response names which rule applied.",
  "inputSchema": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "type": "object",
    "properties": {
      "artifact": {
        "description": "A full ChainGraph artifact envelope (must contain policy_parameters, output_payload, and execution_hash).",
        "type": "object",
        "propertyNames": {
          "type": "string"
        },
        "additionalProperties": {}
      },
      "policy_parameters": {
        "description": "Artifact policy_parameters (if not passing a full artifact).",
        "type": "object",
        "propertyNames": {
          "type": "string"
        },
        "additionalProperties": {}
      },
      "output_payload": {
        "description": "Artifact output_payload (if not passing a full artifact).",
        "type": "object",
        "propertyNames": {
          "type": "string"
        },
        "additionalProperties": {}
      },
      "claimed_hash": {
        "description": "The execution_hash to check against (if not passing a full artifact).",
        "type": "string"
      }
    }
  }
}

